/*
* Página de inicio de sesión
* Implementar:
* - Formulario de login
* - Validación de campos
* - Integración con API de autenticación
*/

import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { authService } from '../services/api';
import Button from '../components/ui/Button';
import '../styles/pages/LoginPage.css';

interface LoginPageProps {
  setAuth: (isAuth: boolean) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ setAuth }) => {
  const navigate = useNavigate();
  
  // Estados
  const [email, setEmail] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  
  // Manejar envío del formulario
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Validar campos - simplificamos la validación
    if (!password.trim()) {
      setError('Por favor, ingresa tu contraseña');
      return;
    }
    
    // Validamos que al menos uno de los campos username o email esté completo
    if (!username.trim() && !email.trim()) {
      setError('Por favor, ingresa tu nombre de usuario o email');
      return;
    }
    
    try {
      setLoading(true);
      setError(null);
      
      // Crear objeto con los datos disponibles
      const loginData: any = {
        password
      };
      
      // Añadir username o email dependiendo de cuál esté disponible
      if (username.trim()) {
        loginData.username = username.trim();
      }
      
      if (email.trim()) {
        // Validar formato de email si se proporciona
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(email)) {
          setError('Por favor, ingresa un email válido');
          setLoading(false);
          return;
        }
        loginData.email = email.trim();
      }
      
      console.log('Intentando login con datos:', loginData);
      
      // Llamar a la API de login con un manejo más robusto
      try {
        // Primero intentamos con la ruta principal
        const response = await authService.login(loginData);
        handleLoginSuccess(response);
      } catch (apiError: any) {
        console.error('Error en ruta principal:', apiError);
        
        // Si el servidor devuelve un mensaje específico, mostrarlo
        if (apiError.response?.data?.message) {
          setError(apiError.response.data.message);
        } else {
          // Si no hay un mensaje específico, mostrar mensaje genérico
          setError('Error al iniciar sesión. Verifica tus credenciales.');
        }
        
        // Si es un error de formato, podemos intentar con un formato alternativo
        if (apiError.response?.status === 422) {
          try {
            console.log('Intentando formato alternativo...');
            // Intenta enviar solo username y password como fallback
            const altResponse = await authService.loginAlternative(username, password);
            handleLoginSuccess(altResponse);
          } catch (altError: any) {
            console.error('Error en formato alternativo:', altError);
            setError('No se pudo iniciar sesión. Verifica tus credenciales o contacta al administrador.');
          }
        }
      }
    } catch (err: any) {
      console.error('Error general en login:', err);
      setError('Error inesperado al conectar con el servidor.');
    } finally {
      setLoading(false);
    }
  };
  
  // Función auxiliar para manejar un login exitoso
  const handleLoginSuccess = (response: any) => {
    console.log('Login exitoso:', response);
    
    // Guardar token si existe
    if (response.data?.token) {
      localStorage.setItem('token', response.data.token);
    }
    
    // Guardar nombre de usuario si existe
    if (response.data?.username) {
      localStorage.setItem('username', response.data.username);
    }
    
    // Actualizar estado de autenticación
    setAuth(true);
    
    console.log('Login exitoso, redirigiendo al menú principal...');
    
    // Redirigir al menú principal
    navigate('/menu');
  };

  return (
    <div className="login-page">
      <div className="login-container">
        <div className="login-header">
          <h1>Heroes&Hostias</h1>
          <h2>Iniciar Sesión</h2>
        </div>
        
        {error && (
          <div className="error-message">{error}</div>
        )}
        
        <form onSubmit={handleSubmit} className="login-form">
          <div className="form-group">
            <label htmlFor="username">Nombre de Usuario</label>
            <input
              type="text"
              id="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              disabled={loading}
              placeholder="Ingresa tu nombre de usuario"
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="email">Correo Electrónico (opcional)</label>
            <input
              type="email"
              id="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              disabled={loading}
              placeholder="O ingresa tu correo electrónico"
            />
          </div>
          
          <div className="form-group">
            <label htmlFor="password">Contraseña</label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              disabled={loading}
              placeholder="Ingresa tu contraseña"
              required
            />
          </div>
          
          <Button 
            type="submit"
            variant="primary"
            size="large"
            disabled={loading}
            className="login-button"
          >
            {loading ? 'Iniciando sesión...' : 'Iniciar Sesión'}
          </Button>
        </form>
        
        <div className="login-footer">
          <p>¿No tienes una cuenta? <Link to="/register">Regístrate</Link></p>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
